    pub const FLAT_MEMORY_RANGE: (usize, usize) = (2, 1);
    pub fn decode_flat_memory_supplied(
        bytes: &[u8],
        offset: usize,
    ) -> Result<bool, openxcvr_core::supplied::SpanError> {
        let buf = openxcvr_core::supplied::field_bytes(bytes, offset, 2, 1)?;
        Ok((buf[0] >> 2) & 1 != 0)
    }

    pub fn set_sff8024_identifier(buf: &mut [u8; 128], value: Sff8024Identifier) {
        buf[0] = value.repr() as u8;
    }

    pub fn set_revision_compliance(buf: &mut [u8; 128], value: Sff8636RevisionCompliance) {
        buf[1] = value.repr() as u8;
    }

    pub fn set_pcie_assigned(buf: &mut [u8; 128], value: [u8; 2]) {
        buf[111..113].copy_from_slice(&value);
    }

    pub fn set_password_change_entry(buf: &mut [u8; 128], value: u32) {
        buf[119..123].copy_from_slice(&value.to_be_bytes());
    }
